  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModel": {
    "value": {
      "screenTime": {
        "usedMinutes": 226,
        "limitMinutes": 240,
        "remainingMinutes": 14,
        "lineText": "还剩14分钟，快到使用上限",
        "reminderText": "快不行了，先休息一下",
        "actionText": "去App设置",
        "status": "warning"
      },
      "state": {
        "staticMock": true,
        "timeoutMock": {
          "limitMinutes": 240,
          "usedMinutes": 226,
          "remainingMinutes": 14,
          "nearTimeout": true
        }
      },
      "asset": {
        "timingIcon": "resources/base/media/icon_timing.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "timing_icon",
      "src": "resources/base/media/icon_timing.png",
      "use": "icon",
      "description": "防沉迷应用用量计时图标，用于表达剩余使用时间和临近超时提醒。",
      "bindTo": "/asset/timingIcon",
      "static": true
    }
  ]
}

